\begin{document}

\section*{Definitions}
\paragraph{Setting: the S-adic homogeneous space X.} Let $G_p=SL_2(\mathbb{Q}_p)$, $G_\infty=SL_2(\mathbb{R})$ ($\mathbb{R}=\mathbb{Q}_\infty$), $G=G_\infty\times G_p$, and let $\Gamma<G$ be a lattice. $X=\Gamma\backslash G$, on which $G$ acts by right translation: $\Gamma(g^z_\infty,g^z_p)\cdot(g_\infty,g_p)=\Gamma(g^z_\infty g_\infty,g^z_p g_p)$. $\mu_\infty,\mu_p$ are Haar measures on $G_\infty,G_p$, $\mu=\mu_\infty\otimes\mu_p$, and $\bar\mu$ is the $G$-invariant probability measure on $X$ induced by $\mu$. $\mathcal{H}=L^2(X,\bar\mu)$ with the right regular representation $\pi$ of $G$.

\paragraph{Spectral decomposition of $L^2(X)$.} $\mathcal{H}=L^2(X)=\int^\oplus_Z\mathcal{H}_{\infty,\xi}\otimes\mathcal{H}_{p,\xi}\,d\mu_Z(\xi)$, $\pi=\int^\oplus_Z\pi_{\infty,\xi}\otimes\pi_{p,\xi}\,d\mu_Z$, each $\pi_{\infty,\xi}$ irreducible unitary of $G_\infty$, with $K_\infty$-eigenbasis $\phi^{(n)}_{\infty,\xi}$, $\pi_{\infty,\xi}(r(\theta))\phi^{(n)}=e^{in\theta}\phi^{(n)}$, $n\in\Sigma(\xi)\subseteq2\mathbb{Z}$ (Bargmann). $\pi_{\infty,\xi}(\Omega_\infty)=\lambda(\xi)\,\mathrm{id}$, $\lambda=s(1-s)$ with $\mathrm{Re}\,s\ge\frac12$, $\mathrm{Im}\,s\ge0$: $s\in\frac12+i\mathbb{R}$ if $\lambda\ge\frac14$, $s\in(\frac12,1]$ if $0\le\lambda<\frac14$, $s\in\mathbb{Z}^+$ if $\lambda<0$. $Z=Z^0\sqcup Z^{rs}\sqcup Z^{ct}$ (cuspidal, residual, continuous spectrum, as in Strömbergsson 2013): $Z^0\cup Z^{rs}$ discrete with counting measure; $Z^{rs}$ finite, containing exactly one $\xi$ with $\pi_{\infty,\xi}$ trivial and $s(\xi)\in(\frac12,1)$ for the others; $s(\xi)\in\frac12+i\mathbb{R}_{\ge0}$ (principal series) on $Z^{ct}$. $Z^0_+=\{\xi\in Z^0: s(\xi)\in(\frac12,1)\}$, $Z^0_-=Z^0\setminus Z^0_+$. $\mathcal{H}^0_+,\mathcal{H}^0_-,\mathcal{H}^{rs},\mathcal{H}^{ct}$ are the closed subspaces over $Z^0_+,Z^0_-,Z^{rs},Z^{ct}$, $\mathcal{H}^0=\mathcal{H}^0_+\oplus\mathcal{H}^0_-$ (cuspidal functions), $\mathcal{H}_\xi=\mathcal{H}_{\infty,\xi}\otimes\mathcal{H}_{p,\xi}$. $\lambda_1=s_1(1-s_1)$ is the smallest Casimir eigenvalue over the nontrivial $\xi\in Z^0_+\cup Z^{rs}$ (assumed to exist, $s_1\in(\frac12,1)$).

\paragraph{Sobolev norm $W_k$.} For $f\in\mathcal{H}$ (smooth vectors $\mathcal{H}^\infty$ dense), $\|f\|_{W_k}=\|(I+\overline{d\pi(\Delta)})^{k/2}f\|_2$, $\Delta=-\sum_iX_i^2\in U(\mathfrak{g}_\infty)$ acting through $G_\infty\times\{1\}$ ($\overline{d\pi(\Delta)}$ is self-adjoint by Nelson); for a pure tensor this is $\|(I+\overline{\pi_\infty(\Delta)})^{k/2}f_\infty\|\cdot\|f_p\|_2$. $W_k(\mathcal{H})$ is the space of $f$ with $\|f\|_{W_k}<\infty$. Up to constants, $\|f\|^2_{W_k}\asymp\int_Z\sum_{n\in\Sigma(\xi)}(1+n^2+|s(\xi)|^2)^k|\langle f_{\xi},\phi^{(n)}_{\infty,\xi}\rangle|^2\,d\mu_Z(\xi)$. Only real derivatives enter: $W_k$ measures smoothness in the $G_\infty$ direction.

% Proof map node exceptional-cuspidal-finite-per-level (claim).
\begin{claim}
Let $X=\Gamma\backslash G$ with $G=SL_2(\mathbb{R})\times SL_2(\mathbb{Q}_p)$ and $\Gamma<G$ a lattice, and let $L^2(X)=\int^\oplus_Z\mathcal{H}_{\infty,\xi}\otimes\mathcal{H}_{p,\xi}d\mu_Z(\xi)$ be its spectral decomposition, with $Z^0_+=\{\xi\in Z^0: s(\xi)\in(\frac12,1)\}$. For every compact open subgroup $K<SL_2(\mathbb{Q}_p)$, the set of $\xi\in Z^0_+$ with $\mathcal{H}_{p,\xi}^{K}\neq0$ (exceptional cuspidal $\xi$ whose $p$-adic factor has a nonzero $K$-fixed vector) is finite, and $\sum_{\xi\in Z^0_+}\dim\mathcal{H}_{p,\xi}^{K}<\infty$.
\end{claim}

\paragraph{Conventions and imported results.} $K<G_p$ acts on $L^2(X)$ through $\{1\}\times K$, and $\mathcal{H}^K$ denotes the fixed vectors of that action. Cuspidality of $\xi$ is never used: the argument works for every discrete $\xi$ with $s(\xi)\in(\frac12,1)$. The proof has no project dependencies; it imports the following classical results, none of which is a project node:
(A) Siegel's lower bound on the coarea of a Fuchsian group \cite{Siegel};
(B) Bargmann's classification of the irreducible unitary representations of $SL_2(\mathbb{R})$ \cite{Bargmann};
(C) finiteness of the Laplace point spectrum below $\frac14$ on a finite-area hyperbolic orbifold \cite{LaxPhillips,Iwaniec};
(D) essential self-adjointness of the Laplacian on a complete Riemannian manifold \cite{Gaffney,Chernoff}.

\begin{proof}
\textbf{Step 1: reduction to a torsion-free $K'$.}
Let
\begin{equation*}
K(p^2)=\{g\in SL_2(\mathbb{Z}_p): g\equiv 1 \bmod p^2\}.
\end{equation*}
Then $K'=K\cap K(p^2)$ is a compact open subgroup with $K'\subset K$. Hence $\mathcal{H}^{K}_{p,\xi}\subset\mathcal{H}^{K'}_{p,\xi}$ for every $\xi$. It therefore suffices to prove
\begin{equation}\label{eq:goal}
\sum_{\xi\in Z^0_+}\dim\mathcal{H}^{K'}_{p,\xi}<\infty .
\end{equation}
Finiteness of the set $\{\xi:\mathcal{H}^K_{p,\xi}\ne0\}$ follows, since each such $\xi$ contributes at least $1$.

\begin{lemma}\label{lem:torsionfree}
$K(p^2)$ is torsion-free, hence so is every subgroup of it and every conjugate $gK'g^{-1}$.
\end{lemma}

\begin{proof}
Let $g\ne1$ have finite order. Some power of $g$ has prime order $\ell$ and is still $\ne 1$ and in $K(p^2)$, so we may assume $g^\ell=1$. Write $g=1+p^kA$ with $k\ge2$ and $A\in M_2(\mathbb{Z}_p)$, $A\not\equiv0 \bmod p$. Then
\begin{equation*}
g^\ell=1+\ell p^kA+\sum_{j\ge2}\binom{\ell}{j}p^{jk}A^j.
\end{equation*}
\begin{itemize}
\item If $\ell\ne p$: $g^\ell\equiv1+\ell p^kA\not\equiv1 \bmod p^{k+1}$.
\item If $\ell=p$: for $2\le j\le p-1$ the term is divisible by $p^{1+2k}$. The $j=p$ term is divisible by $p^{pk}$, and $pk\ge2k\ge k+2$. So $g^p\equiv1+p^{k+1}A\not\equiv1 \bmod p^{k+2}$. This also holds for $p=2$, where the $j=p=2$ term is $p^{2k}A^2$.
\end{itemize}
Both cases contradict $g^\ell=1$.
\end{proof}

\medskip
\textbf{Step 2: $X/K'$ is a finite union of $\Lambda_i\backslash G_\infty$.}
$\Gamma$ acts on the countable discrete set $G_p/K'$ through its $p$-component. Choose representatives $x_i=g_iK'$ of the $\Gamma$-orbits, $i\in I$. Let
\begin{equation*}
\Gamma_i=\{\gamma\in\Gamma:\gamma_pg_iK'=g_iK'\}=\Gamma\cap(G_\infty\times g_iK'g_i^{-1}),\qquad \Lambda_i=\mathrm{pr}_\infty(\Gamma_i)<G_\infty .
\end{equation*}

\emph{(a) $\Lambda_i$ is discrete, and $\mathrm{pr}_\infty$ is injective on $\Gamma_i$.}
\begin{itemize}
\item Kernel: $\ker=\Gamma\cap(\{1\}\times g_iK'g_i^{-1})$ is discrete in a compact group, so finite. By Lemma~\ref{lem:torsionfree} it is trivial.
\item Discreteness: let $\gamma_n\in\Gamma_i$ with $\gamma_{n,\infty}\to1$. Since $\gamma_{n,p}$ lies in the compact set $g_iK'g_i^{-1}$, a subsequence of $\gamma_n$ converges in $G$. As $\Gamma$ is discrete, it is eventually constant, so $\gamma_{n,\infty}=1$ eventually along it. Hence $1$ is not a limit of elements of $\Lambda_i\setminus\{1\}$.
\end{itemize}

\emph{(b) Decomposition and measure.} Let $X_i$ be the image in $X$ of $G_\infty\times\Gamma_pg_iK'$. The $X_i$ are disjoint, open and cover $X$. Let $F_i\subset G_\infty$ be a Borel fundamental domain for $\Lambda_i$.
\begin{itemize}
\item The set $F_i\times g_iK'$ maps onto $X_i$. Given $\Gamma(h,g)$ with $\gamma(h,g)=(h',g_ik)$, write $h'=\lambda h''$ with $h''\in F_i$ and $\lambda=\gamma'_\infty$, $\gamma'\in\Gamma_i$. Then $\gamma'^{-1}(h',g_ik)\in F_i\times g_iK'$.
\item The map is injective. If $\gamma(h,g_ik)=(h',g_ik')$ with $h,h'\in F_i$, then $\gamma\in\Gamma_i$ and $\gamma_\infty h=h'$. So $\gamma_\infty=1$, and $\gamma=1$ by (a).
\end{itemize}
So $F_i\times g_iK'$ is a fundamental domain for $\Gamma$ on the preimage of $X_i$. With $\mu$ left Haar measure, this gives that the $\mu$-mass of $X_i$ is $\mu_\infty(F_i)\,\mu_p(K')$, and
\begin{equation}\label{eq:volume}
\sum_{i\in I}\mu_\infty(\Lambda_i\backslash G_\infty)\,\mu_p(K')=\mu(\Gamma\backslash G)<\infty .
\end{equation}
In particular each $\Lambda_i$ is a lattice in $SL_2(\mathbb{R})$.

\emph{(c) $I$ is finite.} By (A), Siegel's theorem \cite{Siegel}, every lattice in $PSL_2(\mathbb{R})$ has coarea $\ge\pi/21$. Hence there is a $c_\infty>0$, depending only on the normalization of $\mu_\infty$, with $\mu_\infty(\Lambda\backslash G_\infty)\ge c_\infty$ for every lattice $\Lambda<SL_2(\mathbb{R})$. Any uniform positive lower bound suffices here; Kazhdan--Margulis also gives one. So, by \eqref{eq:volume},
\begin{equation*}
|I|\le\frac{\mu(\Gamma\backslash G)}{c_\infty\,\mu_p(K')} .
\end{equation*}

\emph{(d) The isomorphism $U$.} For $f\in L^2(X)^{K'}$, first replace $f$ by its $K'$-average, which is a representative that is right-$K'$-invariant everywhere it is defined. Set $Uf=(F_i)_{i\in I}$ with $F_i(h)=f(\Gamma(h,g_i))$.
\begin{itemize}
\item $F_i$ is left $\Lambda_i$-invariant: for $\gamma\in\Gamma_i$, $f(\Gamma(\gamma_\infty h,g_i))=f(\Gamma(h,\gamma_p^{-1}g_i))$, and $\gamma_p^{-1}g_i\in g_iK'$.
\item By (b),
\begin{equation*}
\|f\|^2_{L^2(X,\bar\mu)}=\frac{\mu_p(K')}{\mu(\Gamma\backslash G)}\sum_{i\in I}\|F_i\|^2_{L^2(\Lambda_i\backslash G_\infty)} .
\end{equation*}
\item Every family $(F_i)$ with finite right-hand side arises this way.
\end{itemize}
So
\begin{equation*}
U:L^2(X)^{K'}\to\bigoplus_{i\in I}L^2(\Lambda_i\backslash G_\infty)
\end{equation*}
is a bijective isometry up to the constant factor. It intertwines $\pi|_{G_\infty\times\{1\}}$ with the right regular representations $\rho_i$; $L^2(X)^{K'}$ is $G_\infty$-invariant because the two factors commute. Consequently $U$ maps $G_\infty$-smooth vectors to smooth vectors and $U\,d\pi(Z)=d\rho(Z)\,U$ on them, for $Z\in\mathfrak{g}_\infty$, and also for $\Omega_\infty$.

\medskip
\textbf{Step 3: exceptional $\xi$ give Laplace eigenfunctions below $\frac14$; count.}
Let $\xi\in Z^0_+$. Since $Z^0$ carries counting measure, $\mathcal{H}_\xi$ is a closed $G$-invariant subspace of $L^2(X)$, and the $\mathcal{H}_\xi$, $\xi\in Z^0$, are mutually orthogonal.

\emph{(a) Spherical vector.} $\pi_{\infty,\xi}$ is irreducible unitary with Casimir eigenvalue $\lambda(\xi)=s(1-s)\in(0,\frac14)$. By (B), Bargmann \cite{Bargmann}, it is the complementary series representation $\pi_s$. Its $K_\infty$-types are $\Sigma(\xi)=2\mathbb{Z}\ni0$. So there is a unit vector $\phi_\xi:=\phi^{(0)}_{\infty,\xi}$ fixed by $K_\infty$. It is a smooth vector, because $K$-finite vectors of irreducible unitary representations are smooth (Harish-Chandra), and $d\pi_{\infty,\xi}(\Omega_\infty)\phi_\xi=\lambda(\xi)\phi_\xi$.

\emph{(b) The vector $\phi_\xi\otimes v$.} For $v\in\mathcal{H}^{K'}_{p,\xi}$, the vector $f=\phi_\xi\otimes v\in\mathcal{H}_\xi$ has the following properties:
\begin{itemize}
\item it is $\{1\}\times K'$-invariant, since $\pi(1,k)f=\phi_\xi\otimes\pi_{p,\xi}(k)v=f$;
\item it is $K_\infty\times\{1\}$-invariant;
\item it is $G_\infty$-smooth, with $d\pi(Z)f=d\pi_{\infty,\xi}(Z)\phi_\xi\otimes v$;
\item consequently $d\pi(\Omega_\infty)f=\lambda(\xi)f$.
\end{itemize}
So $F=(F_i)=Uf$ has each $F_i\in L^2(\Lambda_i\backslash G_\infty)$ right-$K_\infty$-invariant and smooth, with $d\rho_i(\Omega_\infty)F_i=\lambda(\xi)F_i$.

\emph{(c) $F_i$ is a Laplace eigenfunction.} Identify right-$K_\infty$-invariant functions on $\Lambda_i\backslash G_\infty$ with functions on $\Lambda_i\backslash\mathbb{H}$ via $g\mapsto g\cdot i$. On smooth such functions $\Omega_\infty$ acts as
\begin{equation*}
\Delta=-y^2(\partial_x^2+\partial_y^2).
\end{equation*}
This normalization is the one under which the spherical vector of $\pi_s$ has eigenvalue $s(1-s)$, which matches the definition. (The draft marks it as to be checked against the node subgroups-real, where $\Omega_\infty=-\frac14(Y^2+2X_+X_-+2X_-X_+)$.)

For $\psi\in C_c^\infty(\Lambda_i\backslash\mathbb{H})$, which is a smooth vector, the operator $d\rho_i(\Omega_\infty)$ is symmetric on smooth vectors, since each $d\rho_i(Z)$ is skew-symmetric there. Hence
\begin{equation*}
\langle F_i,\Delta\psi\rangle=\langle d\rho_i(\Omega_\infty)F_i,\psi\rangle=\lambda(\xi)\langle F_i,\psi\rangle .
\end{equation*}
So $F_i\in D((\Delta|_{C_c^\infty})^*)$ with $(\Delta|_{C^\infty_c})^*F_i=\lambda(\xi)F_i$. By (D) \cite{Gaffney,Chernoff}, $\Delta|_{C_c^\infty}$ is essentially self-adjoint on the complete hyperbolic orbifold $\Lambda_i\backslash\mathbb{H}$; if $\Lambda_i$ has torsion, pass to a torsion-free finite-index normal subgroup (Selberg's lemma) and take invariants. Therefore $F_i$ lies in the $\lambda(\xi)$-eigenspace $E_i(\lambda(\xi))$ of the self-adjoint Laplacian on $L^2(\Lambda_i\backslash\mathbb{H})$.

\emph{(d) Count.} By (C) (Selberg; Lax--Phillips \cite{LaxPhillips}; Iwaniec \cite{Iwaniec}),
\begin{equation*}
N_i:=\sum_{\lambda\in(0,1/4)}\dim E_i(\lambda)<\infty
\end{equation*}
for every lattice $\Lambda_i<SL_2(\mathbb{R})$. Set $N=\sum_{i\in I}N_i$, which is finite by Step 2(c).

Take any finite set $S\subset Z^0_+$ and finite-dimensional subspaces $V_\xi\subset\mathcal{H}^{K'}_{p,\xi}$, $\xi\in S$. Fix $\lambda\in(0,\frac14)$ and set $S_\lambda=\{\xi\in S:\lambda(\xi)=\lambda\}$.
\begin{itemize}
\item The space $W_\lambda=\bigoplus_{\xi\in S_\lambda}\phi_\xi\otimes V_\xi$ has dimension $\sum_{\xi\in S_\lambda}\dim V_\xi$: the sum is orthogonal across $\xi$, and $v\mapsto\phi_\xi\otimes v$ is isometric.
\item $U$ is injective and maps $W_\lambda$ into $\bigoplus_iE_i(\lambda)$, by (c).
\end{itemize}
Hence $\sum_{\xi\in S_\lambda}\dim V_\xi\le\sum_i\dim E_i(\lambda)$. Summing over the finitely many $\lambda$ that occur gives $\sum_{\xi\in S}\dim V_\xi\le N$. Taking the supremum over all such choices of $S$ and $V_\xi$ gives
\begin{equation*}
\sum_{\xi\in Z^0_+}\dim\mathcal{H}^{K}_{p,\xi}\le\sum_{\xi\in Z^0_+}\dim\mathcal{H}^{K'}_{p,\xi}\le N<\infty ,
\end{equation*}
which is \eqref{eq:goal}. This also covers the case where some $\dim\mathcal{H}^{K'}_{p,\xi}$ is a priori infinite. Finiteness of $\{\xi\in Z^0_+:\mathcal{H}^K_{p,\xi}\ne0\}$ follows.
\end{proof}

\paragraph{Remark.} The bound $N$ depends on $K$ through $K'$ and is not uniform in $K$.

\begin{thebibliography}{9}
\bibitem{Bargmann} V.~Bargmann, Irreducible unitary representations of the Lorentz group, \emph{Ann. of Math.} 48 (1947).
\bibitem{Chernoff} P.~R.~Chernoff, Essential self-adjointness of powers of generators of hyperbolic equations, \emph{J. Funct. Anal.} 12 (1973).
\bibitem{Gaffney} M.~P.~Gaffney, A special Stokes's theorem for complete Riemannian manifolds, \emph{Ann. of Math.} 60 (1954).
\bibitem{Iwaniec} H.~Iwaniec, \emph{Spectral Methods of Automorphic Forms}.
\bibitem{LaxPhillips} P.~D.~Lax and R.~S.~Phillips, \emph{Scattering Theory for Automorphic Functions} (1976).
\bibitem{Siegel} C.~L.~Siegel, Some remarks on discontinuous groups, \emph{Ann. of Math.} 46 (1945).
\end{thebibliography}

\end{document}

