\bibitem{Bargmann} V.~Bargmann, Irreducible unitary representations of the Lorentz group, \emph{Ann. of Math.} 48 (1947).
\bibitem{Chernoff} P.~R.~Chernoff, Essential self-adjointness of powers of generators of hyperbolic equations, \emph{J. Funct. Anal.} 12 (1973).
\bibitem{Gaffney} M.~P.~Gaffney, A special Stokes's theorem for complete Riemannian manifolds, \emph{Ann. of Math.} 60 (1954).
\bibitem{Iwaniec} H.~Iwaniec, \emph{Spectral Methods of Automorphic Forms}.
\bibitem{LaxPhillips} P.~D.~Lax and R.~S.~Phillips, \emph{Scattering Theory for Automorphic Functions} (1976).
\bibitem{Siegel} C.~L.~Siegel, Some remarks on discontinuous groups, \emph{Ann. of Math.} 46 (1945).
