\section*{Definitions}
\paragraph{$p$-adic subgroups $K_p, A_p, H_p, H_p^-$.} $K_p=SL_2(\mathbb{Z}_p)$. $A_p=\{a_p(\omega,n)=\mathrm{diag}(\omega p^n,\omega^{-1}p^{-n}) : n\in\mathbb{Z}_{\ge0},\ \omega\in\mathbb{Z}_p^\times\}$ (a subset of the diagonal group, not a subgroup, since $n\ge0$), $a_n=a_p(1,n)$. $H_p=\{h_p(t)=\begin{pmatrix}1&t\\0&1\end{pmatrix}: t\in\mathbb{Q}_p\}$, $H_p^-=\{h_p^-(t)=\begin{pmatrix}1&0\\t&1\end{pmatrix}: t\in\mathbb{Q}_p\}$.

\paragraph{Real subgroups, Lie algebra basis, Casimir.} $K_\infty=SO(2)=\{r(\theta)=\begin{pmatrix}\cos\theta&\sin\theta\\-\sin\theta&\cos\theta\end{pmatrix}\}$, $A_\infty=\{a_\infty(x)=\mathrm{diag}(e^{x/2},e^{-x/2}): x\ge0\}$ (a subset, not a subgroup, since $x\ge0$), $H_\infty=\{h_\infty(t)=\begin{pmatrix}1&t\\0&1\end{pmatrix}: t\in\mathbb{R}\}$, $H_\infty^-=\{h^-_\infty(t)=\begin{pmatrix}1&0\\t&1\end{pmatrix}\}$. Basis of $\mathfrak{g}_\infty=\mathfrak{sl}_2(\mathbb{R})$: $Y=\mathrm{diag}(1,-1)$, $X_-=\begin{pmatrix}0&0\\1&0\end{pmatrix}$, $X_+=\begin{pmatrix}0&1\\0&0\end{pmatrix}$. For a unitary representation $\pi$ of $G$ and $Z\in\mathfrak{g}_\infty$, $d\pi(Z)f=\lim_{t\to0}(\pi(\exp tZ,1)f-f)/t$. Casimir: $\Omega_\infty=-\frac14(Y^2+2X_+X_-+2X_-X_+)$; $\Delta=-\sum_i X_i^2$ for a fixed basis $\{X_i\}$ of $\mathfrak{g}_\infty$. Burger notation: $a(y)=\mathrm{diag}(y^{1/2},y^{-1/2})=a_\infty(\log y)$ for $y>0$.

\paragraph{$d_K(v)$: dimension of the $K$-span.} For a unitary representation of a group with compact subgroup $K$ and a vector $v$, $d_K(v)=\dim\langle K\cdot v\rangle$, the dimension of the linear span of $\pi(K)v$; $v$ is $K$-finite if $d_K(v)<\infty$.

\paragraph{Harish-Chandra functions $\Xi_\infty, \Xi_p$.} Harish-Chandra functions. Real: $\Xi_\infty(g)=\frac{1}{2\pi}\int_0^{2\pi}\|g^{T}(\cos\theta,\sin\theta)^{T}\|^{-1}\,d\theta$ for $g\in G_\infty$ (bi-$K_\infty$-invariant, $\Xi_\infty(1)=1$, $\Xi_\infty(a_\infty(x))\asymp(1+x)e^{-x/2}$). $p$-adic: $\Xi_p$ is the bi-$K_p$-invariant function on $G_p$ given on the Bruhat-Tits tree ($(p+1)$-regular, base vertex $o$ fixed by $K_p$) by $\Xi_p(g)=p^{-m/2}\big(1+m\frac{p-1}{p+1}\big)$, $m=d(o,g o)$; since $d(o,a_n o)=2n$, $\Xi_p(a_n)=\frac{p^{-n}}{p+1}\big((2n+1)(p-1)+2\big)$.

\paragraph{Decay exponents kappa.} Decay exponent of an irreducible unitary representation (of $G_\infty$ or $G_p$): $\kappa=1-s$ for the complementary series of parameter $s$ (real: $\lambda=s(1-s)$ the Casimir eigenvalue, $s\in(\frac12,1)$; $p$-adic: $\gamma^s$, $s\in(0,1)$ as in the spherical function definition), and $\kappa=1$ for tempered representations. For $\pi=\int^\oplus_Z\pi_{\infty,\xi}\otimes\pi_{p,\xi}\,d\mu_Z(\xi)$: $\kappa_{\infty,\xi}=1-s_\infty(\xi)$, $\kappa_{p,\xi}=1-s_p(\xi)$, and $\kappa_\infty=\operatorname{ess\,inf}_\xi\kappa_{\infty,\xi}$, $\kappa_p=\operatorname{ess\,inf}_\xi\kappa_{p,\xi}$ over the nontrivial components.

% Proof map node real-complementary-decay (claim).
\begin{claim}
Let $\pi$ be a complementary series representation of $G_\infty$ with Casimir eigenvalue $s(1-s)$, $s\in(\frac12,1)$. If $\phi,\psi$ are unit vectors with $\pi(r(\theta))\phi=e^{in\theta}\phi$ and $\pi(r(\theta))\psi=e^{im\theta}\psi$ for some $n,m\in\mathbb{Z}$, then $|\langle\pi(g)\phi,\psi\rangle|\le\Xi_\infty(g)^{1-s}$ for all $g\in G_\infty$.
\end{claim}

\theoremstyle{remark}
\newtheorem*{cited}{Cited fact}
\newtheorem*{remark*}{Remark}

\subsection*{Imported facts}
This node has no project dependencies. Two facts are imported from the literature (cited, not Reference-reviewed): the standard model of the complementary series (M) and the Cowling--Haagerup--Howe theorem (CHH); see the closing remark.

\emph{Reading of the statement} (standing question q\_b51e1af2ff): ``complementary series with Casimir eigenvalue $s(1-s)$'' is read as ``unitarily equivalent to the model $\pi_s$ of (M) below''. The claim is invariant under unitary equivalence (weight vectors and matrix coefficients are transported), so we work in the model.

\subsection*{Notation}
$G=SL_2(\mathbb{R})$, $K=K_\infty$, $dk$ the Haar probability measure on $K$. Iwasawa: every $g\in G$ is uniquely $g=h_\infty(u)a(y)r(\theta)$, with $y=y(g)>0$. For the bottom row, $\mathrm{row}_2(h_\infty(u)a(y)r(\theta))=y^{-1/2}(-\sin\theta,\cos\theta)$, so
\begin{equation*}
y(g)=\|\mathrm{row}_2 g\|^{-2},\qquad y(gk)=y(g),\qquad y(h_\infty(u)a(y')g)=y'\,y(g).
\end{equation*}
$I(s)$ is the space of continuous $f:G\to\mathbb{C}$ with $f(h_\infty(u)a(y)g)=y^sf(g)$, with $\rho(g)f(x)=f(xg)$. Put $e^{(s)}_n(h_\infty(u)a(y)r(\theta))=y^se^{in\theta}$, so $|e^{(s)}_n(g)|=y(g)^s$. Cartan: $g=k_1a_\infty(x)k_2$ with $x=x(g)\ge0$ uniquely determined (operator norm $\|g\|=e^{x/2}$).

\begin{cited}[(M); Knapp, \emph{Representation theory of semisimple groups}, Ch.~II \S5 and Ch.~VII; Lang, \emph{$SL_2(\mathbb{R})$}; Bargmann 1947]
For $s\in(\frac12,1)$ let $I(s)^{\mathrm{ev}}=\{f\in I(s): f(-g)=f(g)\}$. The Knapp--Stein operator $A_sf(g)=\int_{\mathbb{R}}f(w\,h_\infty(t)\,g)\,dt$ ($w=r(\pi/2)$) converges, maps $I(s)\to I(1-s)$, commutes with $\rho$, and
\begin{equation*}
\langle f_1,f_2\rangle_s:=\int_K(A_sf_1)(k)\overline{f_2(k)}\,dk
\end{equation*}
is a $\rho(G)$-invariant, Hermitian, positive definite form on $I(s)^{\mathrm{ev}}$. The completion $H_s$ with the extension of $\rho$ is the complementary series $\pi_s$, irreducible, with Casimir eigenvalue $s(1-s)$. The span of the $e_n$, $n$ even, is dense in $I(s)^{\mathrm{ev}}$ for the $\langle\,,\rangle_s$-topology (Fourier series in $\theta$ of $f|_K$).
\end{cited}

\begin{cited}[(CHH); Cowling--Haagerup--Howe 1988, Thm.~1]
Let $G$ be connected semisimple with finite centre, $K$ maximal compact, and $\sigma$ a unitary representation having a dense subspace on which all coefficients lie in $L^{2+\varepsilon}(G)$ for every $\varepsilon>0$. Then for $K$-finite $v,w$:
\begin{equation*}
|\langle\sigma(g)v,w\rangle|\le(d_K(v)d_K(w))^{1/2}\|v\|\|w\|\,\Xi(g),
\end{equation*}
$\Xi$ Harish-Chandra's function.
\end{cited}

\begin{proof}
\textbf{Step 0 (consequences of (M)).}
\begin{itemize}
\item $A_se^{(s)}_n$ is right-$K$-equivariant of weight $n$ and lies in $I(1-s)$, so $A_se_n^{(s)}=c_ne_n^{(1-s)}$ for a scalar $c_n$. Then $\langle e_n,e_n\rangle_s=c_n\int_K|e_n|^2=c_n$; Hermitian $\Rightarrow c_n\in\mathbb{R}$, positive definite $\Rightarrow c_n>0$ ($n$ even).
\item The $e_n$, $n$ even, are pairwise orthogonal (distinct $K$-weights, $\rho(K)$ unitary) and span a dense subspace of $H_s$ (by (M)).
\item Weight spaces: $H_s(n)=\mathbb{C}e_n$ for $n$ even and $H_s(n)=0$ for $n$ odd, since $P_n=\int_K\overline{\chi_n(k)}\pi(k)\,dk$ is continuous and maps the dense span onto $\mathbb{C}e_n$, resp.\ $0$.
\end{itemize}
Hence (odd weights making the claim vacuous) the unit weight vectors are $\phi=\alpha e_n/\sqrt{c_n}$, $\psi=\beta e_m/\sqrt{c_m}$ with $|\alpha|=|\beta|=1$ and $n,m$ even.

\medskip
\textbf{Step 1 (decay of weight-vector coefficients).}

\emph{1a.} By Hermitian symmetry and $A_se_m=c_me_m^{(1-s)}$,
\begin{equation*}
\langle\rho(g)e_n,e_m\rangle_s=\overline{\langle e_m,\rho(g)e_n\rangle_s}=c_m\int_K\overline{e^{(1-s)}_m(k)}\,e_n(kg)\,dk
\end{equation*}
($\rho(g)e_n\in I(s)^{\mathrm{ev}}$, so the defining formula applies). As $|e^{(1-s)}_m(k)|=1$ and $|e_n(kg)|=y(kg)^s$,
\begin{equation*}
|\langle\pi(g)\phi,\psi\rangle|\le\sqrt{c_m/c_n}\;\Phi_s(g),\qquad\Phi_s(g):=\int_Ky(kg)^s\,dk.
\end{equation*}
$\Phi_s$ is bi-$K$-invariant (left: invariance of $dk$; right: $y(gk)=y(g)$).

\emph{1b.} $\Phi_s(a_\infty(x))\le\frac{2s}{2s-1}e^{-(1-s)x}$ for $x\ge0$. For $k=r(\theta)$, $\mathrm{row}_2(r(\theta)a_\infty(x))=(-e^{x/2}\sin\theta,\,e^{-x/2}\cos\theta)$, so
\begin{equation*}
y=(e^x\sin^2\theta+e^{-x}\cos^2\theta)^{-1},\qquad y^s\le\min\big(e^{sx},\,e^{-sx}|\sin\theta|^{-2s}\big).
\end{equation*}
With $t=\mathrm{dist}(\theta,\pi\mathbb{Z})\in[0,\frac\pi2]$, we have $|\sin\theta|\ge\frac2\pi t$, and each $t$-interval of length $dt$ has $\theta$-measure $4\,dt$:
\begin{equation*}
\Phi_s(a_\infty(x))\le\frac{4}{2\pi}\int_0^{\pi/2}\min\Big(e^{sx},\,e^{-sx}\big(\tfrac{2t}{\pi}\big)^{-2s}\Big)\,dt .
\end{equation*}
Split at $t_0=\frac\pi2e^{-x}\le\frac\pi2$: the part over $[0,t_0]$ is $\le t_0e^{sx}=\frac\pi2e^{-(1-s)x}$; the part over $[t_0,\infty)$ is
\begin{equation*}
\le e^{-sx}\big(\tfrac\pi2\big)^{2s}\frac{t_0^{1-2s}}{2s-1}=\frac{\pi}{2}\,\frac{e^{-(1-s)x}}{2s-1}
\end{equation*}
(using $2s>1$). The total is $\le\frac2\pi\cdot\frac\pi2\big(1+\frac1{2s-1}\big)e^{-(1-s)x}$.

\emph{1c.} Consequently, for any weight vectors $u\in H_s(n)$, $v\in H_s(m)$ and all $g$:
\begin{equation*}
|\langle\pi(g)u,v\rangle|\le C_{n,m}\|u\|\|v\|\,e^{-(1-s)x(g)},\qquad C_{n,m}=\sqrt{c_m/c_n}\,\tfrac{2s}{2s-1}.
\end{equation*}
This constant is not $1$, so Step 1 alone does not give the claim.

\medskip
\textbf{Step 2 (tensor power with almost-$L^2$ coefficients).}
Let $k:=\lceil\frac1{2(1-s)}\rceil$ (so $k\ge2$ and $k(1-s)\ge\frac12$). Let $\sigma:=\pi_s^{\otimes k}$ on the Hilbert tensor product $H_s^{\otimes k}$, $\sigma(g)=\pi_s(g)^{\otimes k}$: it is unitary and strongly continuous (on pure tensors by continuity of each factor; then by uniform boundedness and density). Let $D$ be the algebraic span of the $e_{n_1}\otimes\cdots\otimes e_{n_k}$ ($n_i$ even); it is dense, since the $e_n$ span a dense subspace of $H_s$. For $u,v\in D$, $\langle\sigma(g)u,v\rangle$ is a finite linear combination of products $\prod_{i=1}^k\langle\pi(g)e_{n_i},e_{m_i}\rangle$, so by 1c
\begin{equation*}
|\langle\sigma(g)u,v\rangle|\le C_{u,v}e^{-k(1-s)x(g)}\le C_{u,v}e^{-x(g)/2}.
\end{equation*}
Haar measure in Cartan coordinates (cited: Knapp Prop.~5.28 / Lang Ch.~V) is $dg=c\,\sinh x\,dk_1\,dx\,dk_2$. Hence for every $\varepsilon>0$
\begin{equation*}
\int_G|\langle\sigma(g)u,v\rangle|^{2+\varepsilon}\,dg\le c\,C_{u,v}^{2+\varepsilon}\int_0^\infty e^{-(1+\varepsilon/2)x}\sinh x\,dx<\infty .
\end{equation*}

\medskip
\textbf{Step 3 (CHH applied to weight vectors).}
Apply (CHH) to $\sigma$ with $v=\phi^{\otimes k}$, $w=\psi^{\otimes k}$: $\sigma(r(\theta))v=e^{ikn\theta}v$, so $d_K(v)=1$, likewise $d_K(w)=1$; $\|v\|=\|w\|=1$; and $\langle\sigma(g)v,w\rangle=\langle\pi(g)\phi,\psi\rangle^k$. Therefore
\begin{equation*}
|\langle\pi(g)\phi,\psi\rangle|^k\le\Xi(g).
\end{equation*}

\emph{Identification $\Xi=\Xi_\infty$.} By definition,
\begin{align*}
\Xi_\infty(g)&=\frac1{2\pi}\int_0^{2\pi}\|g^T(\cos\theta,\sin\theta)^T\|^{-1}d\theta=\frac1{2\pi}\int_0^{2\pi}\|(\cos\theta,\sin\theta)g\|^{-1}d\theta\\
&=\int_K\|\mathrm{row}_2(kg)\|^{-1}dk=\int_Ky(kg)^{1/2}dk,
\end{align*}
as, when $k=r(\theta)$ runs over $K$, $\mathrm{row}_2k=(-\sin\theta,\cos\theta)$ runs uniformly over the circle. This is Harish-Chandra's $\Xi=\varphi_0$ (the spherical function of the unitary principal series $I(\frac12)$, $\int_K e^{-\rho(H(kg))}dk$ with $e^{-\rho(H)}\leftrightarrow y^{1/2}$). If the convention of CHH uses the opposite Iwasawa order, it gives $g\mapsto\Xi_\infty(g^{-1})$, which equals $\Xi_\infty(g)$: both are bi-$K$-invariant and $a_\infty(x)^{-1}=r(\frac\pi2)a_\infty(x)r(\frac\pi2)^{-1}$. (Reliance point: this identification is with the cited normalisation of $\Xi$.)

\medskip
\textbf{Step 4 (conclusion).}

\emph{4a. $0<\Xi_\infty\le1$.} Positivity is clear. By Cauchy--Schwarz, $\Xi_\infty(g)\le(\int_Ky(kg)\,dk)^{1/2}$; the right side is bi-$K$-invariant and at $a_\infty(x)$ equals
\begin{equation*}
\Big(\frac1{2\pi}\int_0^{2\pi}\frac{d\theta}{e^x\sin^2\theta+e^{-x}\cos^2\theta}\Big)^{1/2}=\big(1/\sqrt{e^xe^{-x}}\big)^{1/2}=1,
\end{equation*}
by the standard $\int_0^{2\pi}\frac{d\theta}{A\sin^2\theta+B\cos^2\theta}=\frac{2\pi}{\sqrt{AB}}$.

\emph{4b. $\frac1k>1-s$.} $k<\frac1{2(1-s)}+1<\frac1{1-s}$, the last because $1<\frac1{2(1-s)}\iff 1-s<\frac12$.

\emph{4c.} Since $0<\Xi_\infty(g)\le1$ and $\frac1k\ge1-s$,
\begin{equation*}
|\langle\pi(g)\phi,\psi\rangle|\le\Xi_\infty(g)^{1/k}\le\Xi_\infty(g)^{1-s}. \qedhere
\end{equation*}
\end{proof}

\begin{remark*}
The bound is far from sharp: Step 1 gives decay $e^{-(1-s)x}$ while $\Xi_\infty^{1-s}\asymp((1+x)e^{-x/2})^{1-s}$; the content is the constant $1$. The integer $k$ only needs $k(1-s)\ge\frac12$ and $k\le\frac1{1-s}$; the interval $[\frac1{2(1-s)},\frac1{1-s}]$ has length $\ge1$ when $1-s\le\frac12$, which is why $s>\frac12$ is used twice (also in 1b).
\end{remark*}

\begin{remark*}[Where reliance on unreviewed sources sits]
\begin{itemize}
\item (M): existence, invariance and positivity of the intertwining form and density of $K$-finite vectors (Step 0); the Cartan Haar density (Step 2).
\item (CHH) Theorem 1, including the normalisation of $\Xi$ (Step 3). Reference \texttt{cowling-haagerup-howe1988} in the project list (candidate, not reviewed). The restatement in H.~He, \emph{Bounds on smooth matrix coefficients on $L^2$-spaces}, confirms that CHH bounds $K$-finite coefficients of tempered representations by $\Xi$ with $\sqrt{\sum d_\sigma^2}$ constants, which equals $1$ for a single $K_\infty$-type; the exact hypothesis ``dense subspace, $L^{2+\varepsilon}$ for all $\varepsilon$'' is taken from memory of CHH Thm.~1 and should be checked against the original.
\end{itemize}
\end{remark*}

\end{document}

