% Proof map node real-unitary-dual-ktypes (claim).
\begin{claim}
Every nontrivial irreducible unitary representation of $G_\infty=SL_2(\mathbb{R})$ is either tempered or a complementary series representation whose Casimir eigenvalue ($\Omega_\infty$ as in subgroups-real) is $\lambda=s(1-s)$ with $s\in(\frac12,1)$ (Bargmann). In every irreducible unitary representation of $G_\infty$ each character $r(\theta)\mapsto e^{in\theta}$ of $K_\infty$ occurs with multiplicity at most one.
\end{claim}

\begin{remark}[Readings fixed]
\emph{Tempered} is read as in the library (\texttt{library-horo/main.tex}, Def.~tempereddef): there is a dense subspace $V$ with $g\mapsto\langle\pi(g)v,v\rangle\in L^{2+\varepsilon}(G_\infty)$ for all $v\in V$ and all $\varepsilon>0$. We prove more: in every tempered case some nonzero $K_\infty$-weight vector $e$ has $|\langle\pi(g)e,e\rangle|\le 2\,\Xi_\infty(g)$.

\emph{Complementary series with parameter $s$} is read as a nontrivial irreducible unitary representation whose $K_\infty$-weights are all of $2\mathbb{Z}$ and whose Casimir eigenvalue is $\lambda=s(1-s)$, $s\in(\frac12,1)$ (this is how decay-exponent uses the term: through $\lambda$). Step~4 shows that such a representation is determined up to equivalence by $\lambda$, so this agrees with any model. The existence of such a representation is not claimed.
\end{remark}

\subsection*{Cited standard facts (not proved here)}
\begin{itemize}
\item[(F1)] G{\aa}rding/Harish-Chandra: the smooth vectors $H^\infty$ are dense and $\pi(G)$-stable, $d\pi$ is a representation of $\mathfrak{g}$ (hence of $U(\mathfrak{g}_{\mathbb{C}})$) by skew-symmetric operators on $H^\infty$, $\pi(k)d\pi(Z)\pi(k)^{-1}=d\pi(\mathrm{Ad}(k)Z)$, $\pi(f)H\subset H^\infty$ for smooth $f$; $P_nH^\infty\subset H^\infty$. (Lang, \emph{$SL_2(\mathbb{R})$}, Ch.~VI; Knapp, \emph{Representation theory of semisimple groups}, Ch.~III.)
\item[(F2)] Cartan decomposition $G=KA_\infty K$, and Haar measure $c\,\sinh x\,dk_1\,dx\,dk_2$ in these coordinates (Lang Ch.~V; Knapp Prop.~5.28).
\item[(F3)] $C^\infty$ solutions of elliptic equations with real-analytic coefficients are real-analytic (Hopf/Petrowsky/Morrey--Nirenberg); equivalently (Harish-Chandra) $K$-finite, $\mathcal{Z}$-finite vectors are analytic.
\item[(F4)] Unitarity of $I(\frac12+it)$: $\int_KF(kg)\,dk=\int_KF(k)\,dk$ for continuous $F$ with $F(h\,a(y)\,x)=yF(x)$ (Knapp Ch.~II/VII; Lang Ch.~III).
\item[(F5)] Iwasawa: every $g\in G$ is $g=h_\infty(u)a(y)r(\theta)$ uniquely, with analytic coordinates.
\end{itemize}

\subsection*{Notation}
$G=G_\infty=SL_2(\mathbb{R})$, $K=K_\infty$, $\chi_n(r(\theta))=e^{in\theta}$, $dk$ the normalized Haar measure on $K$. $(\pi,H)$ is an irreducible unitary representation. $P_n=\int_K\overline{\chi_n(k)}\pi(k)\,dk$ is the orthogonal projection onto $H(n)=\{v:\pi(r(\theta))v=e^{in\theta}v\}$; $\sum_nP_n=I$ strongly (spectral theorem for the circle), so $H_K=\bigoplus^{\mathrm{alg}}_nH(n)$ is dense. $\pi(f)=\int_Gf(g)\pi(g)\,dg$ for $f\in C_c(G)$. Put $W=X_++X_-$, $R=X_+-X_-$; then $\exp(\theta R)=r(\theta)$, and
\begin{equation*}
[R,Y]=-2W,\qquad [R,W]=2Y,\qquad [Y,W]=2R.
\end{equation*}
$S=\{n:H(n)\ne0\}$.

\begin{proof}
\textbf{Step 1 (multiplicity one; second sentence of the claim).}

\emph{1a.} Let $\mathcal{A}_n=\{f\in C_c(G): f(k_0gk_1)=\overline{\chi_n(k_0)\chi_n(k_1)}f(g)\}$. For $f\in C_c(G)$ put
\begin{equation*}
f^n(g)=\iint\overline{\chi_n(k)\chi_n(k')}\,f(k^{-1}gk'^{-1})\,dk\,dk'.
\end{equation*}
Then $f^n\in\mathcal{A}_n$, $\pi(f^n)=P_n\pi(f)P_n$, and $f^n=f$ for $f\in\mathcal{A}_n$. $\mathcal{A}_n$ is closed under convolution and under $f^*(g)=\overline{f(g^{-1})}$, since $f^*(k_0gk_1)=\overline{f(k_1^{-1}g^{-1}k_0^{-1})}=\overline{\chi_n(k_0)\chi_n(k_1)}f^*(g)$. So $\pi(\mathcal{A}_n)|_{H(n)}$ is a $*$-algebra of bounded operators on $H(n)$.

\emph{1b. $\pi(\mathcal{A}_n)$ acts irreducibly on $H(n)$.} Let $0\ne V\subset H(n)$ be closed and $\pi(\mathcal{A}_n)$-invariant; let $0\ne v\in V$ and $u\in H(n)\ominus V$. For all $f\in C_c(G)$,
\begin{equation*}
\langle\pi(f)v,u\rangle=\langle P_n\pi(f)P_nv,u\rangle=\langle\pi(f^n)v,u\rangle=0.
\end{equation*}
The closed span of $\pi(C_c(G))v$ is $\pi(G)$-invariant (as $\pi(g)\pi(f)=\pi(f(g^{-1}\cdot))$) and contains $v$ (approximate identity, strong continuity), so it is $H$ by irreducibility; hence $u=0$ and $V=H(n)$.

\emph{1c. $\mathcal{A}_n$ is commutative.} Let $\iota(g)=wg^Tw^{-1}$ with $w=\mathrm{diag}(1,-1)$ (conjugation by $w$ is an automorphism of $G$). Then $\iota$ is an anti-automorphism of $G$ with $\iota^2=\mathrm{id}$, $\iota(r(\theta))=w\,r(-\theta)\,w^{-1}=r(\theta)$, and $\iota(a)=a$ for diagonal $a$. $\iota$ preserves Haar measure: $\iota$ is inversion composed with the automorphism $\theta(g)=w(g^T)^{-1}w^{-1}$; $G$ is unimodular, so inversion preserves $dg$; $\theta_*dg=c\,dg$ with $\theta^2=\mathrm{id}$ and $c>0$, so $c=1$. Hence
\begin{equation*}
(f_1*f_2)\circ\iota=(f_2\circ\iota)*(f_1\circ\iota)
\end{equation*}
(substitute $h=\iota(u)$ in $\int f_1(h)f_2(h^{-1}\iota g)\,dh$, using $\iota(u)^{-1}\iota(g)=\iota(gu^{-1})$). For $f\in\mathcal{A}_n$ and $g=k_1ak_2$ (Cartan, F2),
\begin{equation*}
f(\iota g)=f(k_2ak_1)=\overline{\chi_n(k_2)\chi_n(k_1)}f(a)=f(g).
\end{equation*}
So $f\circ\iota=f$ on $\mathcal{A}_n$, and $f_1*f_2=(f_1*f_2)\circ\iota=f_2*f_1$.

\emph{1d.} A $*$-algebra $\mathcal{B}$ of bounded operators acting irreducibly on a Hilbert space has commutant $\mathbb{C}I$: if $T$ commutes with $\mathcal{B}$, so do $T^*$ and the spectral projections of $T+T^*$ and $i(T-T^*)$, whose ranges are closed invariant subspaces, hence $0$ or everything. $\mathcal{B}=\pi(\mathcal{A}_n)|_{H(n)}$ is commutative, so $\mathcal{B}\subset\mathcal{B}'=\mathbb{C}I$; then every closed subspace of $H(n)$ is invariant, and 1b forces $\dim H(n)\le1$. This holds for every irreducible unitary $\pi$, the trivial one included, and proves the second sentence of the claim.

\medskip
\textbf{Step 2 (ladder structure).}

\emph{2a.} By (F1), $H^\infty$ is dense and $P_nH^\infty\subset H^\infty$; $P_n$ is continuous onto $H(n)$ and $\dim H(n)\le1$, so $H(n)=P_nH^\infty\subset H^\infty$. $d\pi$ extends complex-linearly to $U(\mathfrak{g}_{\mathbb{C}})$ on $H^\infty$; $d\pi(Z)$ is skew-symmetric for real $Z$, and $d\pi(R)=in$ on $H(n)$.

\emph{2b.} Let $E_\pm=Y\pm iW$. From the brackets, $[R,E_\pm]=\pm2iE_\pm$, so $d\pi(E_\pm)H(n)\subset H(n\pm2)$. On $H^\infty$, $\langle d\pi(E_+)u,v\rangle=-\langle u,d\pi(E_-)v\rangle$. Further $E_+E_-=Y^2+W^2-2iR$, $E_-E_+=Y^2+W^2+2iR$, and $2X_+X_-+2X_-X_+=W^2-R^2$, so
\begin{equation*}
\Omega_\infty=-\tfrac14(Y^2+W^2-R^2)=-\tfrac14(E_+E_-+2iR-R^2)=-\tfrac14(E_-E_+-2iR-R^2).
\end{equation*}
On $H(n)$: $\Omega=-\frac14(E_+E_- -2n+n^2)=-\frac14(E_-E_++2n+n^2)$.

\emph{2c. Casimir on weight spaces.} $\Omega$ is $\mathrm{Ad}$-invariant, so $d\pi(\Omega)$ commutes with $\pi(K)$ on $H^\infty$ and preserves $H(n)$; as $\dim H(n)\le1$, $d\pi(\Omega)=\lambda_n$ on $H(n)$ with $\lambda_n\in\mathbb{R}$ ($\Omega$ is symmetric).

\emph{2d. Analyticity (F3).} For $v\in H(n)$ and $u\in H$, $F(g)=\langle\pi(g)v,u\rangle$ is $C^\infty$ and $R_ZF(g)=\langle\pi(g)d\pi(Z)v,u\rangle$, where $R_ZF(g)=\frac{d}{dt}F(g\exp tZ)|_{t=0}$. With $L=-(Y^2+W^2+R^2)=4\Omega-2R^2$ (elliptic, left-invariant, analytic coefficients), $R_LF=(4\lambda_n+2n^2)F$. Hence $F$ is real-analytic on $G$, and so is any finite sum of such functions.

\emph{2e. All weights are reachable; $\lambda_n$ is constant.} Fix $n_0\in S$, $0\ne v_0\in H(n_0)$, and let $M=\mathrm{span}\{d\pi(x)v_0: x \text{ a monomial in } E_\pm\}$. $M$ is spanned by weight vectors, so $M=\bigoplus_{n\in S'}H(n)$ for some $S'\subset S$. Put $M'=\bigoplus_{n\in S\setminus S'}H(n)$. $M'$ is $d\pi(E_\pm)$-stable: for $u\in M'$, $v\in M$, $\langle E_+u,v\rangle=-\langle u,E_-v\rangle=0$, and $E_+u$ is a sum of weight vectors (likewise for $E_-$). For $v\in M$, $u\in M'$, $F(g)=\langle\pi(g)v,u\rangle$ is analytic (2d), and every derivative at $e$,
\begin{equation*}
R_{Z_1}\cdots R_{Z_k}F(e)=\langle d\pi(Z_1)\cdots d\pi(Z_k)v,u\rangle,
\end{equation*}
vanishes, since $M$ is $d\pi(\mathfrak{g}_{\mathbb{C}})$-stable ($\mathfrak{g}_{\mathbb{C}}=\langle R,E_+,E_-\rangle$). As $G$ is connected, $F\equiv0$. So $\pi(G)M\perp M'$, the closed $G$-invariant span of $M$ is $\perp M'$, and by irreducibility it is $H$; so $M'=0$ and $S'=S$. Since $\Omega$ is central, $d\pi(\Omega)\,x\,v_0=x\,d\pi(\Omega)v_0=\lambda_{n_0}xv_0$ for every monomial $x$; hence $\lambda_n\equiv\lambda$. Also, every monomial path passes only through weights in $S$, so $S$ is an interval of $n_0+2\mathbb{Z}$ (if $n,n'\in S$ and $n<n'$ then $n+2,\dots,n'-2\in S$). And $\pi(-I)=\pi(r(\pi))=\pm1$ (central, Schur), so all $n\in S$ have the same parity.

\emph{2f. Norm formula.} Take unit vectors $e_n\in H(n)$ ($n\in S$). Write $E_+e_n=a_ne_{n+2}$ ($a_n:=0$ if $n+2\notin S$) and $E_-e_{n+2}=b_ne_n$; by 2b, $b_n=-\overline{a_n}$. From 2b applied to $e_n$, $E_-E_+e_n=-|a_n|^2e_n$, so $\lambda=-\frac14(-|a_n|^2+2n+n^2)$, that is,
\begin{equation*}
|a_n|^2=(n+1)^2-\mu,\qquad \mu:=1-4\lambda\qquad(n\in S).
\end{equation*}
Similarly $E_+E_-e_n=-|a_{n-2}|^2e_n$ gives $|a_{n-2}|^2=(n-1)^2-\mu$ ($a_{n-2}:=0$ if $n-2\notin S$). If $n,n+2\in S$ then $a_n\ne0$ (otherwise $E_+e_n=0=E_-e_{n+2}$ and no monomial crosses from $n$ to $n+2$, against 2e). So for $n\in S$: $n+2\in S\iff(n+1)^2>\mu$, and $n-2\in S\iff(n-1)^2>\mu$. Writing $\lambda=s(1-s)$: $\mu=(2s-1)^2$ and $|a_n|^2=(n+2s)(n+2-2s)$.

\medskip
\textbf{Step 3 (classification of $(S,\lambda)$).}

\emph{A. $S=\{m,\dots,M\}$ finite.} Then $(m-1)^2=\mu=(M+1)^2$. $M+1=m-1$ is impossible, so $M=-m$ and $m\le0$. If $m<M$, then $n=m$ gives $(m+1)^2>(m-1)^2$, i.e.\ $m>0$: a contradiction. So $S=\{0\}$, $H=H(0)$ (density of $H_K$), $\dim H=1$, and $\pi$ is a unitary character of $G=[G,G]$, i.e.\ \textbf{trivial}.

\emph{B. $S=\{m,m+2,\dots\}$.} Then $\mu=(m-1)^2$, and $(m+1)^2>\mu$ gives $m\ge1$; conversely all $n\ge m$ satisfy $(n+1)^2>\mu$. Here $\lambda=\frac m2(1-\frac m2)$ (holomorphic discrete series for $m\ge2$, limit for $m=1$).

\emph{C. $S=\{\dots,M-2,M\}$.} Symmetrically, $\mu=(M+1)^2$ and $M\le-1$.

\emph{D. $S=\varepsilon+2\mathbb{Z}$.} We need $(n+1)^2>\mu$ for all $n\equiv\varepsilon$. Even $\varepsilon$: $\mu<1$, i.e.\ $\lambda>0$. Odd $\varepsilon$ ($n=-1$): $\mu<0$, i.e.\ $\lambda>\frac14$.
\begin{itemize}
\item[D1.] $\mu\le0$ ($\lambda\ge\frac14$, $s=\frac12+it$, $t\ge0$): shown tempered in Step~4.
\item[D2.] $\varepsilon$ even, $0<\mu<1$: $s=\frac{1+\sqrt\mu}2\in(\frac12,1)$ and $\lambda=s(1-s)\in(0,\frac14)$: the \textbf{complementary series} with parameter $s$ (in the reading of the Remark).
\end{itemize}
So a nontrivial $\pi$ falls under B, C, D1 or D2. It remains to show that B, C and D1 are tempered.

\medskip
\textbf{Step 4 (temperedness).}

\emph{4a. From one coefficient to a dense subspace.} Let $0\ne e\in H$ with $\varphi(g)=\langle\pi(g)e,e\rangle\in L^{p}(G)$. For $v=\pi(f)e$, $f\in C_c(G)$,
\begin{equation*}
\langle\pi(g)v,v\rangle=\iint f(h)\overline{f(h')}\,\varphi(h'^{-1}gh)\,dh\,dh',
\end{equation*}
and Minkowski's inequality with unimodularity gives $\|\langle\pi(\cdot)v,v\rangle\|_p\le\|f\|_1^2\|\varphi\|_p$. $V=\{\pi(f)e\}$ is a subspace, and it is dense (its closure is $G$-invariant and contains $e$). Take $p=2+\varepsilon$.

\emph{4b. Integrability (F2).} $\int_GF\,dg=c\int_K\int_0^\infty\int_KF(k_1a_\infty(x)k_2)\sinh x\,dk_1\,dx\,dk_2$, and
\begin{equation*}
\Xi_\infty(a_\infty(x))=\frac1{2\pi}\int_0^{2\pi}(e^x\cos^2\theta+e^{-x}\sin^2\theta)^{-1/2}\,d\theta,
\end{equation*}
which is $\ge e^{-x/2}$ and $\le C(1+x)e^{-x/2}$ (split at $|\theta-\frac\pi2|=e^{-x}$ and its mirror, use that the integrand is $\le\min(e^{-x/2}/|\cos\theta|,\,e^{x/2})$ and $|\cos\theta|\ge\frac2\pi|\theta\mp\frac\pi2|$). Hence $\Xi_\infty\in L^{2+\varepsilon}(G)$, since $((1+x)e^{-x/2})^{2+\varepsilon}\sinh x\le(1+x)^{3}e^{-\varepsilon x/2}$.

\emph{4b$'$. Cases B and C.} In case B let $\varphi(g)=\langle\pi(g)e_m,e_m\rangle$. Then $\varphi(r(\theta)gr(\theta'))=e^{im(\theta+\theta')}\varphi(g)$, $\varphi(1)=1$, and $R_{E_-}\varphi=R_Y\varphi-iR_W\varphi=0$ since $E_-e_m=0$. Let $a_t=\exp tY=a_\infty(2t)$, $t>0$, and $f(t)=\varphi(a_t)$. Since $\mathrm{Ad}(a_t^{-1})R=e^{-2t}X_+-e^{2t}X_-$,
\begin{equation*}
W=\coth(2t)\,R-\frac1{\sinh2t}\,\mathrm{Ad}(a_t^{-1})R.
\end{equation*}
The right derivative along $\mathrm{Ad}(a_t^{-1})R$ at $a_t$ is the left derivative along $R$:
\begin{equation*}
\varphi(a_t\exp(s\,\mathrm{Ad}(a_t^{-1})R))=\varphi(\exp(sR)a_t)=e^{ims}f(t).
\end{equation*}
So $R_W\varphi(a_t)=im(\coth2t-\mathrm{csch}\,2t)f=im\tanh(t)f$, and $f'+m\tanh(t)f=0$, $f(0)=1$, whence $f(t)=\cosh(t)^{-m}$:
\begin{equation*}
|\varphi(k_1a_\infty(x)k_2)|=\cosh(x/2)^{-m}\le2e^{-x/2}\le2\,\Xi_\infty(a_\infty(x))\qquad(m\ge1).
\end{equation*}
So $\varphi\in L^{2+\varepsilon}$ by 4b, and $\pi$ is tempered by 4a. Case C is the same with $E_+e_M=0$: $f'-M\tanh(t)f=0$, $f=\cosh(t)^{-|M|}$.

\emph{4c. Case D1.} \emph{Normalized basis:} choose a unit $e_\varepsilon$, then $e_{n+2}:=E_+e_n/\|E_+e_n\|$ for $n\ge\varepsilon$ and $e_{n-2}:=-E_-e_n/\|E_-e_n\|$ for $n\le\varepsilon$. Then for all $n\in S$: $E_+e_n=\alpha_ne_{n+2}$, $E_-e_{n+2}=-\alpha_ne_n$, $\alpha_n=\sqrt{(n+1)^2-\mu}>0$, $Re_n=ine_n$.

\begin{lemma}[Determination]
If $(\pi,H)$, $(\pi',H')$ are irreducible unitary with the same $(S,\mu)$ and normalized bases $e_n,e'_n$, then $\langle\pi(g)e_n,e_k\rangle=\langle\pi'(g)e'_n,e'_k\rangle$ for all $g\in G$.
\end{lemma}
\begin{proof}
Both sides are analytic (2d), and all their derivatives at $e$ are $\langle d\pi(x)e_n,e_k\rangle$ for monomials $x$ in $R,E_\pm$, computed by the same matrices. $G$ is connected; use the Taylor series in exponential coordinates.
\end{proof}
The same argument gives $\pi\cong\pi'$ via $\pi(g)e_n\mapsto\pi'(g)e'_n$; in particular a representation in case D2 is determined by $\lambda$, which justifies the reading of ``complementary series'' in the Remark.

\emph{Model (F4).} For $s=\frac12+it$ let $I(s)=\{f:G\to\mathbb{C} : f(h_\infty(u)a(y)g)=y^sf(g)\}$ with norm $\|f\|^2=\int_K|f|^2\,dk$ and $\rho(g)f(x)=f(xg)$; it is unitary. Put $e_n(h_\infty(u)a(y)r(\theta))=y^se^{in\theta}$ (Iwasawa, F5). Then $\rho(-I)e_n=(-1)^ne_n$, so $I(s,\varepsilon)=\overline{\mathrm{span}}\{e_n:n\equiv\varepsilon\}$ is invariant. The weight space of weight $n$ is $\mathbb{C}e_n$ (a weight-$n$ $f$ has $f(r(\theta))=f(1)e^{in\theta}$, so $f=f(1)e_n$). Casimir: $R_\Omega e_n=c\,e_n$ ($R_\Omega$ commutes with left translations and with $K$), and $c=(R_\Omega e_n)(1)$ is computed via
\begin{equation*}
\Omega=-\tfrac14(Y^2-2Y+4X_+^2-4X_+R),
\end{equation*}
using $2X_+X_-+2X_-X_+=4X_+X_--2Y$ and $X_-=X_+-R$: $R_{X_+}e_n=0$ on $NA$ (as $h(u)a(y)\exp\tau X_+=h(u+y\tau)a(y)$), and $e_n(\exp\tau Y)=e^{2s\tau}$, so $c=-\frac14(4s^2-4s)=s(1-s)=\lambda$. So $I(s,\varepsilon)$ has $S=\varepsilon+2\mathbb{Z}$ and Casimir eigenvalue $\lambda$; by 2f its $\alpha_n^2=(n+1)^2-\mu>0$ (the D1 condition), hence it is irreducible (a closed invariant $V\ne0$ is $\overline{\bigoplus_{n\in T}}\mathbb{C}e_n$ by $K$-invariance, and $E_\pm$ with $\alpha_n\ne0$ force $T=S$). After rephasing its basis to a normalized one, the determination lemma gives
\begin{equation*}
|\langle\pi(g)e_n,e_n\rangle|=|\langle\rho(g)e'_n,e'_n\rangle|\le\int_K|e_n(kg)|\,dk=\int_K y(kg)^{1/2}\,dk=\Xi_\infty(g),
\end{equation*}
using $|e_n(g)|=\|(0,1)g\|^{-1}$ (the bottom row of $h\,a(y)\,r(\theta)$ is $y^{-1/2}(-\sin\theta,\cos\theta)$) and the definition of $\Xi_\infty$. By 4a and 4b, $\pi$ is tempered.

This proves the first sentence of the claim.
\end{proof}

\begin{remark}[For dependents]
In cases B, C, D1 the weight vector $e$ used satisfies $|\langle\pi(g)e,e\rangle|\le2\,\Xi_\infty(g)$. This is not part of the claim.
\end{remark}

\end{document}

